"""OSHA/OIICS code lookup for the packaged top-50 model labels."""
from __future__ import annotations

import base64
import json
import zlib
from typing import Any, Dict

_DATA = ""

_CODE_MAP: Dict[str, Dict[str, Dict[str, str]]] = json.loads(
    zlib.decompress(base64.b64decode(_DATA)).decode("utf-8")
)


def get_osha_label(task_name: str, label_id: int, fallback_title: str = "") -> Dict[str, str]:
    task = str(task_name).strip().lower()
    item = _CODE_MAP.get(task, {}).get(str(int(label_id)), {})
    return {
        "code": str(item.get("code", "")),
        "title": str(item.get("title", fallback_title)).strip() or str(fallback_title).strip(),
    }


def enrich_prediction_result(prediction_result: Dict[str, Any]) -> Dict[str, Any]:
    for task_name, task_result in prediction_result.get("predictions", {}).items():
        mapped = get_osha_label(task_name, task_result.get("label_id", -1), task_result.get("label", ""))
        task_result["code"] = mapped["code"]
        task_result["title"] = mapped["title"]
        task_result["label"] = mapped["title"]
    return prediction_result
